import logging
from typing import Any, Dict
from urllib.parse import urlparse, urlunparse


logger = logging.getLogger("desktopenv.metrics.chrome")


def is_expected_active_tab_approximate(active_tab_info: Dict[str, str], rule: Dict[str, Any]) -> float:
    """
    Checks if the expected active tab is open in Chrome, ignoring query parameters in the URL.
    """
    if not active_tab_info:
        return 0.

    match_type = rule['type']

    if match_type == "url":
        expected_url = rule['url']
        if isinstance(active_tab_info, dict):
            actual_url = active_tab_info.get('url', None)
        else:
            actual_url = active_tab_info
        from urllib.parse import urlparse, urlunparse
        def strip_query(url):
            parsed = urlparse(url)
            return urlunparse(parsed._replace(query="", fragment="")).rstrip("/")
        expected_norm = strip_query(expected_url)
        actual_norm = strip_query(actual_url)
        if actual_norm == expected_norm or actual_norm.startswith(expected_norm + "/"):
            return 1
        else:
            return 0
    else:
        logger.error(f"Unknown type: {match_type}")
        return 0


def exact_match(result, rules) -> float:
    expect = str(rules["expected"]).strip().lower()
    result = str(result).strip().lower()
    print(result, expect)

    if result == expect:
        return 1.
    else:
        return 0.


def is_in_list(result, rules) -> float:
    expect = rules["expected"]
    if result is None:
        return 0.
    values = result if isinstance(result, list) else [result]
    if any(str(expect) == str(value) or str(expect) in str(value) for value in values):
        return 1.
    else:
        return 0.
